\"^7.0.0\",\n    \"@fission-ai/openspec\": \"1.14.3\",\n    \"@types/node\": \"^24.19.2\",\n    \"oxfmt\": \"^0.62.0\",\n    \"oxlint\": \"^1.77.0\",\n    \"oxlint-tsgolint\": \"^7.0.2004\",\n    \"typescript\": \"^7.0.2\"\n  },\n  \"peerDependencies\": {\n    \"@earendil-works/pi-ai\": \">=0.83.0\",\n    \"@earendil-works/pi-coding-agent\": \">=0.83.0\"\n  },\n  \"pi\": {\n    \"extensions\": [\n      \"./pi-provider-sub2api/index.ts\",\n      \"./pi-custom-provider/index.ts\",\n      \"./pi-continue/index.ts\",\n      \"./pi-skill/index.ts\",\n      \"./pi-model-trace/index.ts\",\n      \"./pi-autocompact/index.ts\",\n      \"./pi-idle-compression/index.ts\",\n      \"./pi-ask/index.ts\"\n    ]\n  }\n}\n"
