      "path": "dsh-autocompact/index.ts",
      "content": "/**\n * Session-only per-model automatic compaction thresholds for dsh.\n *\n * The dsh port of `@indexyz/pi-autocompact`. A `/autocompact 300k` threshold is\n * kept in memory for the current session and model only; when the measured\n * request pressure crosses it, the plugin compacts an explicit balanced surface\n * range through the session's mounted compaction backend before the next\n * request. Nothing is written to configuration, the session log carries only\n * the backend's ordinary compaction records, and the model's real context-window\n * metadata is never modified.\n *\n * `compaction` is not a Host-plane service: the shipped Web bundle disables the\n * root row and lets each Agent preset mount its own isolated instance. This\n * plugin therefore mounts on the Host plane (so one row serves every preset) and\n * addresses the backend of the exact Agent at event time through\n * `agentPresets.serviceFor`, falling back to the Host plane for compositions (the\n * headless, ACP, and SDK bundles) that do mount it there.\n *\n * @module @indexyz/dsh-autocompact\n */\nimport z from \"@deepseek-ai/schemastery\";\nimport { CommandDefinitionId } from \"@deepseek-ai/dsh-commands/brand\";\nimport type { Context } from \"@deepseek-ai/cordis\";\nimport type { Agent } from \"@deepseek-ai/dsh-agent\";\nimport type { AgentPresetRegistry } from \"@deepseek-ai/dsh-agent-preset-registry\";\nimport type { CompactionEngine } from \"@deepseek-ai/dsh-compaction\";\nimport type { CommandInvocation, CommandResult } from \"@deepseek-ai/dsh-commands\";\nimport type { Session } from \"@deepseek-ai/dsh-session\";\nimport { needsCompaction, selectCompactableRange } from \"./compaction.ts\";\nimport {\n  defaultLimits,\n  modelKey,\n  nativeAutoEnabled,\n  nativePolicy,\n  nativeRetainTokens,\n  parseLimit,\n  resolveLimit,\n  supportsRegions,\n  validateDefaultLimit,\n  validateLimit,\n} from \"./settings.ts\";\n\n/** Plugin identity used by the Loader and by diagnostics. */\nexport const name = \"autocompact\";\n\n/** Host-plane services this plugin needs before it can register its command and hook. */\nexport const inject = [\"commands\", \"tokenMeter\", \"llm\"];\n\n/** A `.volatile()` Config field: the Loader parses it into a stable reference read with `get()`. */\nexport interface VolatileField<T> {\n  get(): T | undefined;\n}\n\n/**\n * Row configuration as `apply` receives it.\n *\n * The two fields the Settings page writes are declared `.volatile()`, so the\n * Loader hands `apply` live references rather than plain values; a direct call\n * (tests, embedding) may still pass plain values.\n */\nexport interface AutocompactConfig {\n  /** Optional global default thresholds keyed by exact `provider/model`. Never written by the command. */\n  modelLimits?: Record<string, number> | VolatileField<Record<string, number>>;\n  /**\n   * Optional deployment-wide threshold applied to every model without its own\n   * entry. Absent means those models keep the backend's automatic compaction.\n   */\n  defaultLimit?: number | VolatileField<number | undefined>;\n  /** Recent-tail fallback budget used only when the backend publishes no retention policy. */\n  retainTokens?: number;\n  /** Master switch for the automatic pressure check. */\n  enabled?: boolean | VolatileField<boolean>;\n}\n\n/**\n * Validated row configuration; misconfiguration fails plugin load.\n *\n * `modelLimits`, `defaultLimit` and `enabled` are volatile because the Settings\n * page edits them through the Host settings service: that service only exposes\n * an entry whose schema declares a volatile field (`volatileForm`), and only\n * accepts writes to volatile paths. A volatile field is also what makes an edit\n * visible to the running plugin without a restart. `retainTokens` stays ordinary\n * configuration, editable from `cordis.patch.yml` only.\n */\nexport const Config = z.object({\n  modelLimits: z.dict(z.natural()).default({}).volatile(),\n  defaultLimit: z.natural().volatile(),\n  retainTokens: z.natural().default(20000),\n  enabled: z.boolean().default(true).volatile(),\n});\n\ninterface Target {\n  readonly provider: string;\n  readonly model: string;\n}\n\n/**\n * Read one Config field, whether the Loader handed over a volatile reference or\n * a plain value, and re-read it on every call so a live Settings write is\n * visible to the running plugin.\n *\n * @param field - the parsed field, a volatile reference, or `undefined`.\n * @param fallback - value used when the field is absent or its reference is empty.\n * @returns the current plain value.\n */\nfunction liveValue<T>(field: T | VolatileField<T> | undefined, fallback: T): T {\n  if (field === undefined) return fallback;\n  if (typeof field === \"object\" && field !== null) {\n    const reference = field as VolatileField<T>;\n    if (typeof reference.get === \"function\") return reference.get() ?? fallback;\n  }\n  return field as T;\n}\n\ninterface SessionState {\n  readonly overrides: Map<string, number | null>;\n  readonly warned: Set<string>;\n}\n\ninterface RouteInfo {\n  readonly target: Target;\n  readonly key: string;\n  readonly contextWindow: number | undefined;\n  readonly retainTokens: number;\n}\n\n/** Resolve the exact routed route for one agent, mirroring the backend's own lookup. */\nexport function targetOf(agent: Agent): Target | undefined {\n  const header = agent.session.requestHeader()?.config;\n  if (header !== undefined && header.provider.length > 0 && header.model.length > 0) {\n    return { provider: header.provider, model: header.model };\n  }\n  const options = agent.options;\n  if (\n    typeof options?.provider === \"string\" &&\n    options.provider.length > 0 &&\n    typeof options.model === \"string\" &&\n    options.model.length > 0\n  ) {\n    return { provider: options.provider, model: options.model };\n  }\n  return undefined;\n}\n\n/**\n * Resolve the compaction backend serving one Agent.\n *\n * A preset-mounted backend is isolated to that Agent's preset realm, so the\n * Agent's own identity is the only key that reaches it. Both dsh 0.2.0-rc.2 and\n * 0.2.1-rc.2 expose that lookup as {@link AgentPresetRegistry.serviceFor} on the\n * `agentPresets` service. The 0.2.1 line dropped the free `serviceForAgent`\n * export; a static import of the missing name fails module evaluation and the\n * plugin never activates. Compositions that mount a backend on the Host plane\n * are served by the direct lookup instead.\n *\n * @param ctx - this plugin's Host-plane context.\n * @param agent - the Agent whose backend is requested.\n * @returns the backend, or `undefined` when this composition mounts none.\n */\nexport function backendFor(ctx: Context, agent: Agent): CompactionEngine | undefined {\n  try {\n    // No service, or a registry object without the method: there is no preset\n    // backend. A throw from a torn-down scope is the same outcome, below.\n    const presets: AgentPresetRegistry | undefined = ctx.get(\"agentPresets\");\n    const mounted = presets?.serviceFor?.(agent, \"compaction\");\n    if (mounted !== undefined) return mounted;\n  } catch {\n    // A torn-down scope or an absent preset runtime leaves only the Host plane.\n  }\n  return ctx.get(\"compaction\");\n}\n\n/**\n * Register the session-only `/autocompact` command and the automatic pressure\n * check for every Agent.\n *\n * @param ctx - Host-plane context carrying the command registry, the token meter, and the LLM registry.\n * @param config - validated row configuration; the Settings-editable fields arrive as live references.\n */\nexport function apply(ctx: Context, config: AutocompactConfig = {}): void {\n  /** Current global defaults, re-read so a Settings write applies to the running plugin. */\n  const limitsNow = (): Map<string, number> =>\n    defaultLimits({ modelLimits: liveValue(config.modelLimits, {}) });\n  /**\n   * Current deployment-wide threshold, re-read like the defaults above.\n   * `undefined` means no default: uncovered models keep the backend's behavior.\n   */\n  const defaultLimitNow = (): number | undefined =>\n    validateDefaultLimit(liveValue<number | undefined>(config.defaultLimit, undefined));\n  const fallbackRetainTokens = liveValue(config.retainTokens, 20000);\n  // Validate the configured defaults at load, where a bad row fails loudly,\n  // instead of at the first measured step.\n  limitsNow();\n  defaultLimitNow();\n  // Session-only state, keyed by the live Session object so a new, resumed, or\n  // forked session starts clean and a detached session is collected.\n  const sessions = new WeakMap<Session, SessionState>();\n\n  const stateOf = (session: Session): SessionState => {\n    let state = sessions.get(session);\n    if (state === undefined) {\n      state = { overrides: new Map(), warned: new Set() };\n      sessions.set(session, state);\n    }\n    return state;\n  };\n\n  const warnOnce = (session: Session, message: string): void => {\n    const { warned } = stateOf(session);\n    if (warned.has(message)) return;\n    warned.add(message);\n    ctx.logger.warn(`autocompact: ${message}`);\n  };\n\n  /** Resolve the exact route, its real window, and the backend's retained-tail budget. */\n  const routeInfo = async (\n    agent: Agent,\n    backend: CompactionEngine,\n    signal?: AbortSignal,\n  ): Promise<RouteInfo | undefined> => {\n    const target = targetOf(agent);\n    if (target === undefined) return undefined;\n    const info = await ctx.llm.resolveModelInfo(target.provider, target.model, signal);\n    const contextWindow = info.context?.contextWindow;\n    const reserved = agent.session.requestHeader()?.config.maxTokens ?? info.defaultMaxTokens ?? 0;\n    return {\n      target,\n      key: modelKey(target.provider, target.model),\n      contextWindow,\n      retainTokens:\n        contextWindow === undefined\n          ? fallbackRetainTokens\n          : nativeRetainTokens(\n              nativePolicy(backend),\n              target.provider,\n              target.model,\n              contextWindow,\n              reserved,\n              fallbackRetainTokens,\n            ),\n    };\n  };\n\n  /**\n   * Compact an explicit balanced range once the session crosses its effective\n   * threshold. Failures are contained: the turn continues untouched, exactly\n   * like the backend's own automatic pressure path.\n   */\n  const checkPressure = async (agent: Agent, signal: AbortSignal): Promise<void> => {\n    if (!liveValue(config.enabled, true) || signal.aborted) return;\n    const target = targetOf(agent);\n    if (target === undefined) return;\n    const key = modelKey(target.provider, target.model);\n    const limit = resolveLimit(\n      stateOf(agent.session).overrides,\n      limitsNow(),\n      key,\n      defaultLimitNow(),\n    );\n    if (limit === undefined) return;\n    const backend = backendFor(ctx, agent);\n    if (backend === undefined || !nativeAutoEnabled(backend)) return;\n    const measurement = ctx.tokenMeter.measure(agent.session);\n    if (!needsCompaction(measurement, limit)) return;\n    if (!supportsRegions(backend)) {\n      warnOnce(\n        agent.session,\n        \"the mounted compaction backend does not support compactRegion; thresholds have no effect\",\n      );\n      return;\n    }\n    const route = await routeInfo(agent, backend, signal);\n    if (route === undefined || route.contextWindow === undefined) {\n      warnOnce(\n        agent.session,\n        `no context capacity for ${key}; configure contextWindow on that adapter model`,\n      );\n      return;\n    }\n    if (signal.aborted) return;\n    validateLimit(limit, route.contextWindow, route.retainTokens);\n    const range = selectCompactableRange(agent.session, measurement, route.retainTokens);\n    if (range === undefined) return;\n    ctx.logger.info(\n      `autocompact: compacting ${key} above ${limit.toLocaleString(\"en-US\")} tokens (${measurement.totalTokens.toLocaleString(\"en-US\")} measured)`,\n    );\n    await backend.compactRegion(range.start, range.end, agent, signal);\n  };\n\n  ctx.on(\"agent/pre-step\", async ({ agent, signal }, next) => {\n    try {\n      await checkPressure(agent, signal);\n    } catch (error) {\n      if (!signal.aborted) {\n        warnOnce(\n          agent.session,\n          `compaction failed: ${error instanceof Error ? error.message : String(error)}`,\n        );\n      }\n    }\n    return next();\n  });\n\n  const handler = async (invocation: CommandInvocation): Promise<CommandResult> => {\n    const { agent, rawInput, signal } = invocation;\n    try {\n      const target = targetOf(agent);\n      if (target === undefined) return { kind: \"error\", text: \"No model selected\" };\n      const key = modelKey(target.provider, target.model);\n      const backend = backendFor(ctx, agent);\n      if (backend === undefined) {\n        return { kind: \"error\", text: `No compaction backend is mounted for ${key}` };\n      }\n      if (!supportsRegions(backend)) {\n        return {\n          kind: \"error\",\n          text: \"Autocompact requires a compaction backend that supports compactRegion (dsh-compaction 0.2.0-rc.2 or newer)\",\n        };\n      }\n      const nativeOff = !nativeAutoEnabled(backend);\n      const route = await routeInfo(agent, backend, signal);\n      if (route === undefined || route.contextWindow === undefined) {\n        return {\n          kind: \"error\",\n          text: `No context capacity for ${key}; configure contextWindow on that adapter model`,\n        };\n      }\n      const input = rawInput.trim().toLowerCase();\n      const state = stateOf(agent.session).overrides;\n      if (input === \"off\") state.set(key, null);\n      else if (input === \"default\") state.delete(key);\n      else if (input) {\n        const limit = parseLimit(input);\n        validateLimit(limit, route.contextWindow, route.retainTokens);\n        if (nativeOff) {\n          return {\n            kind: \"error\",\n            text: \"Automatic compaction is disabled by the compaction backend. Enable it before setting a threshold.\",\n          };\n        }\n        state.set(key, limit);\n      }\n      const defaults = limitsNow();\n      const limit = resolveLimit(state, defaults, key, defaultLimitNow());\n      // Name the layer the effective threshold came from: the session, an exact\n      // `provider/model` default, or the deployment-wide fallback.\n      const source = state.has(key)\n        ? \"session\"\n        : defaults.has(key)\n          ? \"global default\"\n          : \"deployment default\";\n      const threshold =\n        limit === undefined\n          ? \"backend default compaction (no plugin threshold)\"\n          : `autocompact above ${limit.toLocaleString(\"en-US\")} tokens (${source})`;\n      return {\n        kind: \"success\",\n        text: `${key}: ${threshold}. Native automatic compaction: ${nativeOff ? \"disabled\" : \"enabled\"}. No configuration written.`,\n      };\n    } catch (error) {\n      return { kind: \"error\", text: error instanceof Error ? error.message : String(error) };\n    }\n  };\n\n  ctx.effect(\n    () =>\n      ctx.commands.register({\n        definitionId: CommandDefinitionId(\"@indexyz/dsh-autocompact\"),\n        name: \"autocompact\",\n        description:\n          \"Session-only per-model compaction threshold: /autocompact [300k | off | default]\",\n        input: { hint: \"300k | off | default\" },\n        handler,\n      }),\n    \"dsh-autocompact command\",\n  );\n}\n"
    },
    {
      "path": "dsh-autocompact/settings.ts",
      "content": "/**\n * Threshold parsing, global defaults, validation, and read-only introspection\n * of the mounted compaction backend's native retention policy.\n *\n * Nothing in this module writes configuration: the command only keeps an\n * in-memory session map, exactly like `pi-autocompact` never writes settings.\n *\n * @module @indexyz/dsh-autocompact/settings\n */\n\n/** Untrusted JSON-shaped configuration object. */\nexport type Settings = Record<string, unknown>;\n\n/** One exact `provider/model` route key, the unit every threshold is keyed by. */\nexport function modelKey(provider: string, model: string): string {\n  return `${provider}/${model}`;\n}\n\n/** Reject a non-object configuration value, tolerating `undefined` for absent sections. */\nexport function object(value: unknown, label: string): Settings {\n  if (value === undefined) return {};\n  if (!value || typeof value !== \"object\" || Array.isArray(value)) {\n    throw new Error(`${label} must be an object`);\n  }\n  return value as Settings;\n}\n\n/**\n * Parse `300k`, `0.3m`, or `300000` into a positive safe integer token count.\n * `k`/`m` are decimal units, matching the reference extension.\n */\nexport function parseLimit(input: string): number {\n  const match = /^(\\d+(?:\\.\\d+)?)([km]?)$/i.exec(input.trim());\n  if (!match) throw new Error(\"Usage: /autocompact [300k | 1m | 300000 | off | default]\");\n  const limit = Number(match[1]) * ({ k: 1000, m: 1000000 }[match[2].toLowerCase()] ?? 1);\n  if (!Number.isSafeInteger(limit) || limit <= 0) {\n    throw new Error(\"Threshold must be a positive safe integer number of tokens\");\n  }\n  return limit;\n}\n\n/**\n * Validate one absolute threshold against the recent-tail budget the compaction\n * backend will keep verbatim and against the real model context window.\n */\nexport function validateLimit(limit: number, contextWindow: number, retainTokens: number): void {\n  if (!Number.isSafeInteger(limit) || limit <= retainTokens) {\n    throw new Error(\n      `Threshold must be an integer greater than the retained token budget (${retainTokens})`,\n    );\n  }\n  if (!Number.isSafeInteger(contextWindow) || contextWindow <= 0 || limit >= contextWindow) {\n    throw new Error(`Threshold must be less than the model context window (${contextWindow})`);\n  }\n}\n\n/**\n * Validate the optional deployment-wide threshold.\n *\n * `undefined` means \"no default\": a model without its own threshold keeps the\n * backend's automatic compaction. A configured value must be a positive safe\n * integer, the same rule every `modelLimits` entry follows.\n */\nexport function validateDefaultLimit(value: unknown): number | undefined {\n  if (value === undefined) return undefined;\n  if (typeof value !== \"number\" || !Number.isSafeInteger(value) || value <= 0) {\n    throw new Error(\"autocompact.defaultLimit must be a positive safe integer number of tokens\");\n  }\n  return value;\n}\n\n/**\n * Optional global defaults from this plugin's own `config`; the command never\n * writes them and a session command overrides them without persisting anything.\n */\nexport function defaultLimits(config: { modelLimits?: unknown }): Map<string, number> {\n  const models = object(config.modelLimits, \"autocompact.modelLimits\");\n  return new Map(\n    Object.entries(models).map(([key, value]) => {\n      if (\n        !key.includes(\"/\") ||\n        typeof value !== \"number\" ||\n        !Number.isSafeInteger(value) ||\n        value <= 0\n      ) {\n        throw new Error(`Invalid autocompact.modelLimits entry: ${key}`);\n      }\n      return [key, value];\n    }),\n  );\n}\n\n/**\n * Resolve the effective absolute threshold for one route.\n *\n * A session override always wins, including an explicit `null` that suppresses\n * every persisted layer. Below it an exact `provider/model` entry wins over the\n * deployment-wide default; with neither configured the route has no threshold\n * and autocompact stays off for it.\n */\nexport function resolveLimit(\n  overrides: ReadonlyMap<string, number | null>,\n  defaults: ReadonlyMap<string, number>,\n  key: string,\n  defaultLimit?: number,\n): number | undefined {\n  if (overrides.has(key)) return overrides.get(key) ?? undefined;\n  return defaults.get(key) ?? defaultLimit;\n}\n\n/** Native compaction policy a backend happens to expose for read-only introspection. */\nexport interface NativeCompactionPolicy {\n  readonly auto?: boolean;\n  readonly retainRatio?: number;\n  readonly retainTokens?: number;\n  readonly modelPolicies?: readonly {\n    readonly provider?: string;\n    readonly model?: string;\n    readonly retainRatio?: number;\n    readonly retainTokens?: number;\n  }[];\n}\n\n/**\n * Read the mounted backend's native policy without depending on a concrete\n * backend package. Any engine that does not publish a `config` object simply\n * yields `undefined`, and the plugin then uses its own fallback budget.\n */\nexport function nativePolicy(engine: unknown): NativeCompactionPolicy | undefined {\n  if (!engine || typeof engine !== \"object\") return undefined;\n  const config = (engine as { config?: unknown }).config;\n  if (!config || typeof config !== \"object\" || Array.isArray(config)) return undefined;\n  return config as NativeCompactionPolicy;\n}\n\n/**\n * Whether the mounted backend still performs automatic compaction. An absent\n * policy counts as enabled, so unknown backends keep working.\n */\nexport function nativeAutoEnabled(engine: unknown): boolean {\n  return nativePolicy(engine)?.auto !== false;\n}\n\n/**\n * Whether the mounted backend supports compacting an explicit surface region,\n * which is the capability an earlier threshold is expressed through.\n */\nexport function supportsRegions(engine: unknown): boolean {\n  return typeof (engine as { compactRegion?: unknown } | undefined)?.compactRegion === \"function\";\n}\n\nfunction tokenCount(value: unknown): number | undefined {\n  if (typeof value !== \"number\" || !Number.isSafeInteger(value) || value < 0) return undefined;\n  return value;\n}\n\n/**\n * Resolve the recent-tail budget for one exact route the same way the native\n * backend's `resolveCompactSpec` does: an exact `provider/model` policy wins,\n * then the backend default, and the plugin fallback applies only when the\n * backend publishes no usable retention policy at all.\n */\nexport function nativeRetainTokens(\n  policy: NativeCompactionPolicy | undefined,\n  provider: string,\n  model: string,\n  contextWindow: number,\n  reservedCompletionTokens: number,\n  fallback: number,\n): number {\n  const override = policy?.modelPolicies?.find(\n    (entry) => entry.provider === provider && entry.model === model,\n  );\n  const absolute = tokenCount(override?.retainTokens) ?? tokenCount(policy?.retainTokens);\n  if (absolute !== undefined) return absolute;\n  const ratio = override?.retainRatio ?? policy?.retainRatio;\n  const messageBudget = contextWindow - reservedCompletionTokens;\n  if (typeof ratio === \"number\" && Number.isFinite(ratio) && ratio >= 0 && messageBudget > 0) {\n    return Math.floor(messageBudget * ratio);\n  }\n  return fallback;\n}\n"
    },
    {
      "path": "dsh-autocompact/compaction.ts",
      "content": "/**\n * Surface range selection for an earlier, session-only compaction threshold.\n *\n * This is the dsh translation of `pi-autocompact`'s `planCompaction`: instead of\n * planning over Pi's projected boundary context, it selects an inclusive\n * positional range on the dsh session surface, keeping the priced recent tail\n * verbatim and never splitting one step's assistant tool-call from its result.\n *\n * @module @indexyz/dsh-autocompact/compaction\n */\nimport { toolPairingBalancedBefore } from \"@deepseek-ai/dsh-compaction\";\nimport type { Session, SessionSeq } from \"@deepseek-ai/dsh-session\";\nimport type { TokenMeasurement } from \"@deepseek-ai/dsh-token-meter\";\n\n/** One inclusive positional span on the session surface. */\nexport interface CompactableRange {\n  /** First surface-node seq to replace, inclusive. */\n  readonly start: SessionSeq;\n  /** Last surface-node seq to replace, inclusive. */\n  readonly end: SessionSeq;\n}\n\n/**\n * Whether the measured request pressure already crossed the effective absolute\n * threshold. Unknown or absent usage is never above it.\n */\nexport function needsCompaction(\n  measurement: Pick<TokenMeasurement, \"totalTokens\">,\n  limit: number,\n): boolean {\n  const tokens = measurement.totalTokens;\n  return typeof tokens === \"number\" && tokens > limit;\n}\n\n/** The `system/message` occupying surface node 0, or `undefined` for other heads. */\nexport function systemHead(session: Session, headSeq: SessionSeq) {\n  const head = session.eventAt(headSeq);\n  return head?.type === \"system/message\" ? head : undefined;\n}\n\n/**\n * Resolve the next range starting at the first non-system surface node while\n * retaining a priced recent tail and never splitting an assistant\n * tool-call/result pair. A `system/message` at surface node 0 is never inside\n * the range; without one the range starts at node 0.\n *\n * Returns `undefined` when the surface is too small or one indivisible\n * oversized message cannot be compacted and still shrink, which leaves the\n * decision to the backend's own overflow or manual compaction.\n *\n * @param session - session supplying authoritative current surface positions.\n * @param measurement - pressure and surface measurement from the token meter.\n * @param retainTokens - minimum recent tail budget retained verbatim.\n * @returns the inclusive positional seq range to compact, or `undefined`.\n */\nexport function selectCompactableRange(\n  session: Session,\n  measurement: Pick<TokenMeasurement, \"nodes\">,\n  retainTokens: number,\n): CompactableRange | undefined {\n  const pricedNodes = measurement.nodes;\n  if (pricedNodes.length === 0) return undefined;\n  const surfaceNodes = session.surface.nodes;\n  if (\n    surfaceNodes.length !== pricedNodes.length ||\n    surfaceNodes.some((seq, index) => seq !== pricedNodes[index]?.seq)\n  ) {\n    throw new Error(\"autocompact: token-meter surface does not match the current session surface\");\n  }\n  const firstIdx = systemHead(session, surfaceNodes[0]) === undefined ? 0 : 1;\n  let accumulated = 0;\n  let keepFromIdx = pricedNodes.length;\n  for (let index = pricedNodes.length - 1; index >= 0; index -= 1) {\n    accumulated += pricedNodes[index].tokens;\n    keepFromIdx = index;\n    if (accumulated >= retainTokens) break;\n  }\n  if (keepFromIdx <= firstIdx) return undefined;\n  while (keepFromIdx > firstIdx) {\n    if (toolPairingBalancedBefore(session, surfaceNodes[keepFromIdx])) break;\n    keepFromIdx -= 1;\n  }\n  if (keepFromIdx <= firstIdx) return undefined;\n  return {\n    start: surfaceNodes[firstIdx],\n    end: surfaceNodes[keepFromIdx - 1],\n  };\n}\n"
    },
    {
      "path": "dsh-autocompact/src/client/status-dock.tsx",
      "content": "/**\n * The autocompact status line in the composer's ambient row.\n *\n * A session's model can carry an autocompact threshold, and the one question\n * this entry answers at a glance is \"will this session compact early, and how\n * close is it?\". It sits beside the session's turn, token, and context readings,\n * and opens this plugin's threshold page when the user acts on it. It reads:\n *\n * - the session's current route from the `modelSelection` projection,\n * - the measured pressure from the `contextPressure` projection,\n * - the configured thresholds from {@link module:@indexyz/dsh-autocompact/client/config-store}.\n *\n * The configured value is the deployment default for that route, or the\n * deployment-wide default when the route has no entry of its own. A session can\n * override it with `/autocompact`, and that override lives in Host memory for\n * the session only, so this line reports the persisted value rather than\n * claiming to be the effective one.\n *\n * @module @indexyz/dsh-autocompact/client/status-dock\n */\n\nimport * as React from \"react\";\nimport { getSnapshot, load, subscribe } from \"./config-store.ts\";\nimport { NS } from \"./contracts.ts\";\nimport type { Translate } from \"./contracts.ts\";\nimport { formatTokens } from \"./limits.ts\";\nimport { layoutFace, openSettingsSection } from \"./services.ts\";\nimport { CSS } from \"./styles.ts\";\n\n/** Route half of the `modelSelection` projection's view. */\ninterface ModelSelection {\n  readonly provider: string;\n  readonly model: string;\n}\n\n/** The `modelSelection` projection's view. */\ninterface ModelSelectionView {\n  /** The selection the next request uses, once chosen. */\n  readonly lastUsed: ModelSelection | null;\n  /** The pending selection, or the last used one. */\n  readonly next: ModelSelection | null;\n}\n\n/** The `contextPressure` projection's view. */\ninterface ContextPressureView {\n  readonly contextWindow?: number;\n  /** Prompt-side pressure of the last reported request. */\n  readonly pressureTokens?: number;\n  /** That pressure plus the surface's movement since the sample. */\n  readonly projectedTokens?: number;\n}\n\n/** A projection reader as the slot kit passes one in. */\ntype ProjectionReader = (key: string) => unknown;\n\n/** Props the slot kit hands this entry beyond the bound translator. */\nexport interface AutocompactStatusProps {\n  readonly t: Translate;\n  /** The slot kit's standard props, including `useProjection`. */\n  readonly kit?: Readonly<Record<string, unknown>>;\n}\n\n/** Stand-in reader for a composition whose kit has no projection hook. */\nconst noProjection: ProjectionReader = () => undefined;\n\n/** Resolve the kit's projection hook, or a reader that always answers absent. */\nfunction readerOf(kit: Readonly<Record<string, unknown>> | undefined): ProjectionReader {\n  const hook = kit?.[\"useProjection\"];\n  return typeof hook === \"function\" ? (hook as ProjectionReader) : noProjection;\n}\n\n/** The `provider/model` route a selection denotes. */\nfunction routeOf(view: ModelSelectionView | undefined): string | undefined {\n  const picked = view?.next ?? view?.lastUsed;\n  return picked === null || picked === undefined ? undefined : `${picked.provider}/${picked.model}`;\n}\n\n/** The freshest pressure figure the projection reports. */\nfunction pressureOf(view: ContextPressureView | undefined): number | undefined {\n  return view?.projectedTokens ?? view?.pressureTokens;\n}\n\n/**\n * The icon that identifies this entry.\n *\n * Copies the artwork of the host's `IconDataOutlineRegular`: the context store\n * with its old rounds folded away, `currentColor`, on the 16-unit grid with a 1px\n * stroke — the pill CSS renders it at 14px, the same as the icons beside it.\n * Copied rather than imported because a bundle plugin must not load a Harness\n * Client package.\n */\nfunction StatusIcon(): React.ReactElement {\n  return (\n    <svg\n      width=\"16\"\n      height=\"16\"\n      viewBox=\"0 0 16 16\"\n      fill=\"none\"\n      xmlns=\"http://www.w3.org/2000/svg\"\n      aria-hidden=\"true\"\n      strokeWidth=\"1\"\n    >\n      <path\n        d=\"M7.8667 0.349609C8.96906 0.349634 10.0601 0.481272 11.0317 0.735352C11.9973 0.987845 12.8453 1.362 13.4644 1.84766C14.0744 2.32629 14.507 2.95539 14.5161 3.69336H14.5171V8.53516C14.0843 8.32076 13.6108 8.17679 13.1108 8.11816C13.1831 7.96848 13.2162 7.82856 13.2163 7.70312V5.76758C12.6269 6.16618 11.8739 6.47995 11.0317 6.7002C10.0602 6.95423 8.96896 7.08494 7.8667 7.08496C6.76461 7.08493 5.67411 6.95415 4.70264 6.7002C3.85994 6.48006 3.10694 6.1662 2.51709 5.76758V7.70312L2.521 7.78418C2.56374 8.19554 2.93361 8.74414 3.91357 9.23145C4.9281 9.73585 6.35004 10.0371 7.8667 10.0371C8.26373 10.0371 8.6543 10.0141 9.03271 9.97461C8.75596 10.3799 8.54664 10.8349 8.42041 11.3232C8.23666 11.3313 8.0518 11.3369 7.8667 11.3369C6.20108 11.3369 4.57025 11.01 3.33447 10.3955C3.04163 10.2499 2.76658 10.0836 2.51709 9.90039V11.6738C2.51728 12.1379 2.88589 12.7556 3.92236 13.292C4.93457 13.8157 6.35342 14.1289 7.8667 14.1289C8.12318 14.1289 8.37694 14.1161 8.62646 14.0986C8.82021 14.5535 9.08999 14.9682 9.41943 15.3271C8.91285 15.3934 8.39149 15.4287 7.8667 15.4287C6.19761 15.4287 4.56379 15.0869 3.32568 14.4463C2.11244 13.8185 1.21649 12.8562 1.21631 11.6738V3.76367C1.21595 3.74853 1.21438 3.733 1.21436 3.71777C1.21436 2.96917 1.65103 2.33053 2.26807 1.84668C2.88747 1.36112 3.73675 0.987685 4.70264 0.735352C5.67413 0.481376 6.76457 0.349636 7.8667 0.349609ZM7.8667 1.65039C6.86269 1.65042 5.88326 1.77028 5.03076 1.99316C4.17183 2.2176 3.50421 2.52956 3.06982 2.87012C2.65043 3.19909 2.52622 3.48898 2.51709 3.69336V3.74414C2.52719 3.94845 2.65185 4.23772 3.06982 4.56543C3.50425 4.90601 4.17172 5.21795 5.03076 5.44238C5.88326 5.66527 6.8627 5.78513 7.8667 5.78516C8.8707 5.78513 9.85015 5.66525 10.7026 5.44238C11.5611 5.21787 12.2286 4.9049 12.6626 4.56445C13.0982 4.22252 13.2163 3.9231 13.2163 3.71777L13.2104 3.63574C13.1818 3.43623 13.044 3.16941 12.6626 2.87012C12.2286 2.52957 11.5614 2.21773 10.7026 1.99316C9.85009 1.77025 8.8708 1.65041 7.8667 1.65039Z\"\n        fill=\"currentColor\"\n      />\n      <path\n        d=\"M12.8936 10.0361L13.2061 10.5566C13.2296 10.5959 13.2651 10.6562 13.3027 10.707C13.3469 10.7666 13.4148 10.8431 13.5195 10.9023C13.6244 10.9617 13.725 10.9801 13.7988 10.9873C13.8619 10.9934 13.9318 10.9932 13.9775 10.9932H14.6162L14.8896 11.4502L14.5947 11.9443C14.5698 11.9859 14.5312 12.0483 14.5029 12.1084C14.4781 12.1611 14.4514 12.2312 14.4395 12.3164L14.4326 12.4072L14.4395 12.4971C14.4514 12.5825 14.4781 12.6532 14.5029 12.7061C14.5312 12.7661 14.5689 12.8287 14.5938 12.8701L14.8896 13.3633L14.6162 13.8213H13.9775C13.9318 13.8213 13.8619 13.821 13.7988 13.8271C13.7433 13.8326 13.6728 13.8442 13.5967 13.875L13.5195 13.9121C13.4148 13.9714 13.3469 14.0478 13.3027 14.1074C13.265 14.1583 13.2296 14.2186 13.2061 14.2578L12.8936 14.7783H12.3115L11.999 14.2578C11.9755 14.2186 11.9401 14.1583 11.9023 14.1074C11.8693 14.0628 11.823 14.0083 11.7578 13.959L11.6855 13.9121L11.6074 13.875C11.5316 13.8445 11.4615 13.8325 11.4062 13.8271C11.3432 13.821 11.2733 13.8213 11.2275 13.8213H10.5889L10.3135 13.3633L10.6104 12.8701C10.6352 12.8287 10.6739 12.7661 10.7021 12.7061C10.7352 12.6357 10.7724 12.534 10.7725 12.4072C10.7724 12.2804 10.7352 12.1788 10.7021 12.1084C10.6739 12.0483 10.6353 11.9859 10.6104 11.9443L10.3135 11.4502L10.5889 10.9932H11.2275C11.2733 10.9932 11.3432 10.9934 11.4062 10.9873C11.4801 10.9801 11.5808 10.9616 11.6855 10.9023C11.7903 10.843 11.8582 10.7666 11.9023 10.707C11.94 10.6562 11.9755 10.5959 11.999 10.5566L12.3115 10.0361H12.8936Z\"\n        stroke=\"currentColor\"\n        strokeMiterlimit=\"10\"\n      />\n    </svg>\n  );\n}\n\n/**\n * Send the user to this plugin's thresholds.\n *\n * Settings owns the panel, its section navigation, and the store behind both, so\n * the shell's own `openSection` is the real destination; the central panel this\n * plugin registers carries the same editor and is only the fallback, for a\n * composition where the settings shell's store cannot be reached (a renamed cell\n * or action, or a profile without settings). Both calls are guarded — `selectPanel`\n * throws for an unregistered key, and a pill must never take the composer row down.\n */\nfunction openThresholds(): void {\n  try {\n    if (openSettingsSection(NS)) return;\n  } catch (error) {\n    console.error(\"[dsh-autocompact] opening the settings section failed:\", error);\n  }\n  try {\n    layoutFace()?.selectPanel(NS);\n  } catch (error) {\n    console.error(\"[dsh-autocompact] opening the threshold panel failed:\", error);\n  }\n}\n\n/**\n * One ambient pill: the entry's icon and its reading, and a way to act on it.\n *\n * The icon carries the identity and the title carries the meaning, so no word of\n * this plugin's name takes space in a row the session's own readings share.\n */\nfunction StatusPill(props: {\n  readonly state: \"on\" | \"off\";\n  readonly title: string;\n  readonly text: string;\n}): React.ReactElement {\n  return (\n    <button\n      type=\"button\"\n      className=\"dsha-status\"\n      data-state={props.state}\n      title={props.title}\n      aria-label={props.title}\n      onClick={openThresholds}\n    >\n      <style>{CSS}</style>\n      <StatusIcon />\n      <span>{props.text}</span>\n    </button>\n  );\n}\n\n/**\n * Render the status entry.\n *\n * The ambient row is shared with the session's own readings, so this entry only\n * takes a seat when it has something to report: a threshold that applies to this\n * session's model, or a master switch that has turned every threshold off. A row\n * that is merely not configured for this model says nothing — the Settings page\n * is where \"not configured\" is discovered and fixed.\n */\nexport function AutocompactStatus(props: AutocompactStatusProps): React.ReactElement | null {\n  const t = props.t;\n  const read = readerOf(props.kit);\n  // Both reads are unconditional: the kit's hook is a hook, and the reader\n  // resolves this session's row before the early returns below.\n  const selection = read(\"modelSelection\") as ModelSelectionView | undefined;\n  const pressure = read(\"contextPressure\") as ContextPressureView | undefined;\n  const snapshot = React.useSyncExternalStore(subscribe, getSnapshot);\n\n  React.useEffect(() => {\n    void load();\n  }, []);\n\n  if (snapshot.state !== \"ready\") return null;\n\n  const enabled = snapshot.config.enabled;\n  const route = routeOf(selection);\n  // The route's own entry wins; without one the deployment default covers it.\n  const limit =\n    route === undefined\n      ? undefined\n      : (snapshot.config.limits[route] ?? snapshot.config.defaultLimit);\n  // An off switch was a deliberate choice and is what stops every threshold, so it\n  // is reported whatever model the session uses.\n  if (!enabled) {\n    return (\n      <StatusPill\n        state=\"off\"\n        title={t(\"dockTitleOff\", { action: t(\"dockAction\") })}\n        text={t(\"dockOff\")}\n      />\n    );\n  }\n  // Under an on switch, a model with no threshold is a non-event: no seat.\n  if (limit === undefined) return null;\n\n  const threshold = formatTokens(limit);\n  const now = pressureOf(pressure);\n  if (now === undefined) {\n    return (\n      <StatusPill\n        state=\"on\"\n        title={t(\"dockTitleLimit\", {\n          route: route ?? \"\",\n          limit: threshold,\n          action: t(\"dockAction\"),\n        })}\n        text={threshold}\n      />\n    );\n  }\n  // The host writes this pair as `used / capacity`; this pill reads the same way,\n  // with the pressure in force first and the threshold that triggers it second.\n  return (\n    <StatusPill\n      state=\"on\"\n      title={t(\"dockTitleLimitNow\", {\n        route: route ?? \"\",\n        limit: threshold,\n        tokens: formatTokens(now),\n        action: t(\"dockAction\"),\n      })}\n      text={`${formatTokens(now)} / ${threshold}`}\n    />\n  );\n}\n"
    },
    {
      "path": "dsh-autocompact/src/client/dictionary.ts",
      "content": "/**\n * This half's own strings.\n *\n * Registered under {@link NS} through the locale service; a lookup miss returns\n * the key, so a missing entry degrades to visible text rather than a crash.\n *\n * @module @indexyz/dsh-autocompact/client/dictionary\n */\n\n/** This module's own strings, one dictionary per locale it ships. */\nexport const DICT: Record<string, Record<string, string>> = {\n  en: {\n    nav: \"Autocompact\",\n    title: \"Autocompact\",\n    intro: \"Compact a session earlier than the backend default, per model or with a default.\",\n    enabled: \"Use automatic thresholds\",\n    enabledHint: \"Applies to every threshold below.\",\n    defaultLimit: \"Default threshold\",\n    defaultLimitHint: \"Applies to every model without its own threshold. Empty: off for them.\",\n    models: \"Per-model thresholds\",\n    modelsHint: \"Token counts; `k` and `m` are units.\",\n    empty: \"No thresholds yet.\",\n    add: \"Add a model\",\n    provider: \"Provider\",\n    model: \"Model\",\n    threshold: \"Threshold\",\n    thresholdPlaceholder: \"300k\",\n    choose: \"Select…\",\n    addAction: \"Add\",\n    save: \"Save\",\n    saving: \"Saving…\",\n    saved: \"Saved.\",\n    discard: \"Discard\",\n    remove: \"Remove\",\n    loading: \"Loading…\",\n    unavailable: \"No autocompact row in this profile; install the bundle to set thresholds.\",\n    readOnly: \"Read-only profile: thresholds cannot be edited.\",\n    noCatalog: \"No model catalog; type the route below.\",\n    manual: \"Route (provider/model)\",\n    invalid: \"Use a positive count such as 300k or 1m.\",\n    duplicate: \"Already configured.\",\n    conflict: \"Changed elsewhere; reloaded with current values.\",\n    failed: \"Could not save: {message}\",\n    toggleFailed: \"Could not toggle: {message}\",\n    dockOff: \"Off\",\n    // The tooltip stays two short lines: what the reading is, and what a click does.\n    dockAction: \"Click to open settings\",\n    dockTitleLimit: \"{route}: compact above {limit}\\n{action}\",\n    dockTitleLimitNow: \"{route}: {tokens} of {limit}\\n{action}\",\n    dockTitleOff: \"Thresholds are off\\n{action}\",\n    crash: \"This page failed to render. Reload; if it keeps failing, report the stack below.\",\n  },\n  zh: {\n    nav: \"自动压缩\",\n    title: \"自动压缩\",\n    intro: \"让会话比后端默认更早压缩：可按模型设置，也可设置默认阈值。\",\n    enabled: \"启用自动阈值\",\n    enabledHint: \"对下面所有阈值生效。\",\n    defaultLimit: \"默认阈值\",\n    defaultLimitHint: \"对所有未单独设置阈值的模型生效；留空则这些模型不启用。\",\n    models: \"按模型设置阈值\",\n    modelsHint: \"token 数；`k`、`m` 为单位。\",\n    empty: \"尚未配置阈值。\",\n    add: \"添加模型\",\n    provider: \"Provider\",\n    model: \"模型\",\n    threshold: \"阈值\",\n    thresholdPlaceholder: \"300k\",\n    choose: \"请选择…\",\n    addAction: \"添加\",\n    save: \"保存\",\n    saving: \"保存中…\",\n    saved: \"已保存。\",\n    discard: \"放弃\",\n    remove: \"删除\",\n    loading: \"加载中…\",\n    unavailable: \"当前 profile 没有 autocompact 行；安装 bundle 后即可设置阈值。\",\n    readOnly: \"只读 profile，无法修改阈值。\",\n    noCatalog: \"暂无模型目录，请在下方手动填写路由。\",\n    manual: \"路由（provider/model）\",\n    invalid: \"请填正整数 token 数，如 300k、1m。\",\n    duplicate: \"该模型已配置。\",\n    conflict: \"配置已被改动，已重新加载最新值。\",\n    failed: \"保存失败：{message}\",\n    toggleFailed: \"切换失败：{message}\",\n    dockOff: \"已关闭\",\n    // 两行以内：一行读数含义，一行点击去向。\n    dockAction: \"点击打开设置\",\n    dockTitleLimit: \"{route}：超过 {limit} 即压缩\\n{action}\",\n    dockTitleLimitNow: \"{route}：{tokens} / {limit}\\n{action}\",\n    dockTitleOff: \"自动阈值已关闭\\n{action}\",\n    crash: \"本页渲染失败。刷新窗口；若仍失败，请把下面的堆栈反馈给作者。\",\n  },\n};\n"
    },
    {
      "path": "dsh-autocompact/src/client/page.tsx",
      "content": "/**\n * The Settings → Autocompact page.\n *\n * The page owns the edit state (the view read from the Host, the staged draft\n * for the deployment default and for each model, the add-model selection) and\n * talks to the Host through the two Remote namespaces in `services.ts`; the two\n * editable views it renders live beside it.\n *\n * @module @indexyz/dsh-autocompact/client/page\n */\n\nimport * as React from \"react\";\nimport { AddModel } from \"./add-model.tsx\";\nimport { publishView } from \"./config-store.ts\";\nimport type { CatalogGroup, NamespaceView, SettingsOp, Translate } from \"./contracts.ts\";\nimport { NS } from \"./contracts.ts\";\nimport { messageOf, parseLimit } from \"./limits.ts\";\nimport { pickNamespace, settingsFace, sessionFace } from \"./services.ts\";\nimport {\n  addKeyOf,\n  defaultChanged,\n  hasChanges,\n  hasRow,\n  manualRouteOf,\n  type Notice,\n  type Pick,\n  type Status,\n  toDefaultLimit,\n  toEntries,\n  type ViewState,\n  visibleRows,\n} from \"./state.ts\";\nimport { CSS } from \"./styles.ts\";\nimport { ThresholdList } from \"./threshold-list.tsx\";\n\n/** The Settings → Autocompact page. */\nexport function AutocompactPage(props: { readonly t: Translate }): React.ReactElement {\n  const t = props.t;\n  const [status, setStatus] = React.useState<Status>({ kind: \"loading\" });\n  const [state, setState] = React.useState<ViewState | null>(null);\n  const [draft, setDraft] = React.useState<Record<string, string>>({});\n  /** Staged text for the deployment-wide threshold; blank means unset. */\n  const [defaultDraft, setDefaultDraft] = React.useState(\"\");\n  const [added, setAdded] = React.useState<string[]>([]);\n  const [removed, setRemoved] = React.useState<string[]>([]);\n  const [pick, setPick] = React.useState<Pick>({\n    provider: \"\",\n    model: \"\",\n    limit: \"\",\n    manualRoute: \"\",\n  });\n  const [catalog, setCatalog] = React.useState<{ groups?: readonly CatalogGroup[] } | null>(null);\n  const [busy, setBusy] = React.useState(false);\n  const [notice, setNotice] = React.useState<Notice | null>(null);\n\n  const applyView = React.useCallback((view: NamespaceView | undefined, writable?: unknown) => {\n    const value = view?.value ?? {};\n    const defaultLimit = toDefaultLimit(value.defaultLimit);\n    // Every view this page reads or writes is also the freshest one the composer\n    // status line can have, so share it instead of making it re-read the row.\n    publishView(view, writable);\n    setState({\n      writable: writable !== false,\n      // The settings namespace is the Loader entry id the Host reported, which\n      // may be prefixed in a composed profile; writes address it verbatim.\n      ns: view?.ns ?? NS,\n      revision: view?.revision,\n      enabled: value.enabled !== false,\n      defaultLimit,\n      limits: toEntries(value.modelLimits),\n    });\n    setDraft({});\n    setDefaultDraft(defaultLimit === undefined ? \"\" : String(defaultLimit));\n    setAdded([]);\n    setRemoved([]);\n  }, []);\n\n  const load = React.useCallback(async () => {\n    const settings = settingsFace();\n    if (settings === undefined) {\n      setStatus({ kind: \"unavailable\" });\n      return;\n    }\n    setStatus({ kind: \"loading\" });\n    try {\n      const response = await settings.describe();\n      if (!response.ok) {\n        setStatus({ kind: \"error\", message: response.error?.message ?? t(\"unavailable\") });\n        return;\n      }\n      const view = pickNamespace(response.value);\n      if (view === undefined) {\n        setStatus({ kind: \"unavailable\" });\n        return;\n      }\n      applyView(view, response.value.writable);\n      setStatus({ kind: \"ready\" });\n    } catch (error) {\n      setStatus({ kind: \"error\", message: messageOf(error) });\n    }\n  }, [applyView, t]);\n\n  React.useEffect(() => {\n    void load();\n  }, [load]);\n\n  React.useEffect(() => {\n    const session = sessionFace();\n    if (session === undefined) return;\n    let cancelled = false;\n    void (async () => {\n      try {\n        const response = await session.modelCatalog();\n        if (!cancelled && response.ok) setCatalog(response.value);\n      } catch {\n        // The manual route field below stays available.\n      }\n    })();\n    return () => {\n      cancelled = true;\n    };\n  }, []);\n\n  const groups: readonly CatalogGroup[] = React.useMemo(\n    () => (Array.isArray(catalog?.groups) ? (catalog.groups as readonly CatalogGroup[]) : []),\n    [catalog],\n  );\n  const selectedGroup = React.useMemo(\n    () => groups.find((group) => group.id === pick.provider),\n    [groups, pick.provider],\n  );\n\n  const rows = React.useMemo(\n    () => visibleRows(state, added, draft, removed),\n    [state, added, draft, removed],\n  );\n\n  const dirty = hasChanges(state, added, removed, draft) || defaultChanged(state, defaultDraft);\n\n  const save = React.useCallback(async () => {\n    const settings = settingsFace();\n    if (settings === undefined || state === null) return;\n    const ops: SettingsOp[] = [];\n    const trimmedDefault = defaultDraft.trim();\n    if (trimmedDefault === \"\") {\n      // Blank means \"no deployment default\"; only a stored value needs the unset.\n      if (state.defaultLimit !== undefined) ops.push({ op: \"unset\", path: [\"defaultLimit\"] });\n    } else {\n      const parsed = parseLimit(trimmedDefault);\n      if (parsed === undefined) {\n        setNotice({ kind: \"error\", text: t(\"invalid\") });\n        return;\n      }\n      if (parsed !== state.defaultLimit) {\n        ops.push({ op: \"set\", path: [\"defaultLimit\"], value: parsed });\n      }\n    }\n    for (const key of removed) ops.push({ op: \"unset\", path: [\"modelLimits\", key] });\n    for (const [key, raw] of Object.entries(draft)) {\n      const parsed = parseLimit(raw);\n      if (parsed === undefined) {\n        setNotice({ kind: \"error\", text: t(\"invalid\") });\n        return;\n      }\n      ops.push({ op: \"set\", path: [\"modelLimits\", key], value: parsed });\n    }\n    if (ops.length === 0) return;\n    setBusy(true);\n    setNotice(null);\n    try {\n      const response = await settings.mutate(state.ns, ops, state.revision);\n      if (response.ok) {\n        applyView(response.value, state.writable);\n        setNotice({ kind: \"success\", text: t(\"saved\") });\n        return;\n      }\n      if (response.error?.code === \"settings/conflict\") {\n        setNotice({ kind: \"warn\", text: t(\"conflict\") });\n        await load();\n        return;\n      }\n      setNotice({\n        kind: \"error\",\n        text: t(\"failed\", { message: response.error?.message ?? \"unknown\" }),\n      });\n    } catch (error) {\n      setNotice({ kind: \"error\", text: t(\"failed\", { message: messageOf(error) }) });\n    } finally {\n      setBusy(false);\n    }\n  }, [state, removed, draft, defaultDraft, applyView, load, t]);\n\n  const setEnabled = React.useCallback(\n    async (next: boolean) => {\n      const settings = settingsFace();\n      if (settings === undefined || state === null) return;\n      setBusy(true);\n      setNotice(null);\n      try {\n        const response = await settings.update(state.ns, { enabled: next }, state.revision);\n        if (response.ok) {\n          applyView(response.value, state.writable);\n          return;\n        }\n        if (response.error?.code === \"settings/conflict\") {\n          setNotice({ kind: \"warn\", text: t(\"conflict\") });\n          await load();\n          return;\n        }\n        setNotice({\n          kind: \"error\",\n          text: t(\"toggleFailed\", { message: response.error?.message ?? \"unknown\" }),\n        });\n      } catch (error) {\n        setNotice({ kind: \"error\", text: t(\"toggleFailed\", { message: messageOf(error) }) });\n      } finally {\n        setBusy(false);\n      }\n    },\n    [state, applyView, load, t],\n  );\n\n  const manualRoute = React.useMemo(() => manualRouteOf(pick), [pick]);\n  const key = addKeyOf(groups, pick, manualRoute);\n  const duplicate = hasRow(rows, key);\n\n  const addEntry = React.useCallback(() => {\n    if (key === \"\" || duplicate) return;\n    if (parseLimit(pick.limit) === undefined) {\n      setNotice({ kind: \"error\", text: t(\"invalid\") });\n      return;\n    }\n    setNotice(null);\n    setAdded((current) => [...current, key]);\n    setDraft((current) => ({ ...current, [key]: pick.limit }));\n    setPick({ provider: \"\", model: \"\", limit: \"\", manualRoute: \"\" });\n  }, [key, duplicate, pick.limit, t]);\n\n  /** Stage one edited threshold value; kept out of `draft` until saved. */\n  const setDraftValue = React.useCallback((entryKey: string, value: string) => {\n    setDraft((current) => ({ ...current, [entryKey]: value }));\n  }, []);\n\n  const removeEntry = React.useCallback((entryKey: string) => {\n    setAdded((current) => current.filter((value) => value !== entryKey));\n    setDraft((current) => {\n      const next = { ...current };\n      delete next[entryKey];\n      return next;\n    });\n    setRemoved((current) => (current.includes(entryKey) ? current : [...current, entryKey]));\n  }, []);\n\n  const body: React.ReactNode[] = [];\n  if (status.kind === \"loading\") {\n    body.push(\n      <p key=\"loading\" className=\"dsha-hint\">\n        {t(\"loading\")}\n      </p>,\n    );\n  } else if (status.kind === \"unavailable\" || status.kind === \"error\") {\n    body.push(\n      <p key=\"unavailable\" className=\"dsha-notice dsha-notice-warn\" role=\"status\">\n        {status.kind === \"error\" ? status.message : t(\"unavailable\")}\n      </p>,\n    );\n  } else if (state !== null) {\n    const readOnly = state.writable === false;\n    if (readOnly) {\n      body.push(\n        <p key=\"readonly\" className=\"dsha-notice dsha-notice-warn\" role=\"status\">\n          {t(\"readOnly\")}\n        </p>,\n      );\n    }\n    body.push(\n      <div key=\"switch\" className=\"dsha-card\">\n        <div className=\"dsha-row\">\n          <div className=\"dsha-row-text\">\n            <span className=\"dsha-row-label\">{t(\"enabled\")}</span>\n            <span className=\"dsha-hint\">{t(\"enabledHint\")}</span>\n          </div>\n          <button\n            type=\"button\"\n            role=\"switch\"\n            aria-checked={state.enabled ? \"true\" : \"false\"}\n            aria-label={t(\"enabled\")}\n            className=\"dsha-switch\"\n            disabled={busy || readOnly}\n            onClick={() => void setEnabled(!state.enabled)}\n          />\n        </div>\n      </div>,\n    );\n\n    body.push(\n      <div key=\"default\" className=\"dsha-card\">\n        <div className=\"dsha-row\">\n          <div className=\"dsha-row-text\">\n            <span className=\"dsha-row-label\">{t(\"defaultLimit\")}</span>\n            <span className=\"dsha-hint\">{t(\"defaultLimitHint\")}</span>\n          </div>\n          <input\n            className=\"dsha-input dsha-value\"\n            value={defaultDraft}\n            placeholder={t(\"thresholdPlaceholder\")}\n            disabled={busy || readOnly}\n            aria-invalid={\n              defaultDraft.trim() !== \"\" && parseLimit(defaultDraft) === undefined\n                ? \"true\"\n                : \"false\"\n            }\n            aria-label={t(\"defaultLimit\")}\n            onChange={(event) => setDefaultDraft(event.target.value)}\n          />\n        </div>\n      </div>,\n    );\n\n    body.push(\n      <div key=\"models\" className=\"dsha-card\">\n        <div className=\"dsha-row-text\">\n          <span className=\"dsha-row-label\">{t(\"models\")}</span>\n          <span className=\"dsha-hint\">{t(\"modelsHint\")}</span>\n        </div>\n        <div className=\"dsha-list\">\n          <ThresholdList\n            t={t}\n            rows={rows}\n            draft={draft}\n            busy={busy}\n            readOnly={readOnly}\n     